import type { catalog } from "@/lib/catalog";
import type { Assessment } from "@/lib/python-assessments";

export type CourseLesson = {
  id: string;
  title: string;
  label: string;
  explanation: string;
  example: string;
  sourceIds: string[];
  assessment: Assessment;
};

type Companion = Omit<CourseLesson, "id" | "title" | "label">;

function lesson(explanation: string, example: string, question: string, answers: [string, string, string], assignment: string, criteria: string[], sourceIds: string[] = []): Companion {
  // Rotate the correct option so the quizzes do not teach a fixed answer position.
  const answer = question.length % 3;
  const options: [string, string, string] = answer === 0 ? [...answers] : answer === 1 ? [answers[2], answers[0], answers[1]] : [answers[1], answers[2], answers[0]];
  return { explanation, example, sourceIds, assessment: { question, options, answer, explanation: `${answers[0]}. ${explanation}`, assignment, criteria } };
}

