export function getCourseLessons(course: (typeof catalog)[number]): CourseLesson[] {
  const content = companions[course.slug];
  if (!content) throw new Error(`Missing curriculum for ${course.slug}`);
  if (Object.keys(content).length !== course.videos.length) throw new Error(`Curriculum count mismatch for ${course.slug}`);
  return course.videos.map((video, index) => {
    const companion = content[video.id];
    if (!companion) throw new Error(`Missing companion for ${course.slug}/${video.id}`);
    const day = video.title.match(/\bday[\s-]*(\d+)/i)?.[1];
    const label = day ? `Day ${Number(day)}` : `Lesson ${index + 1}`;
    return { ...companion, id: video.id, title: video.title, label };
  });
}
